      renwu = "npc",
      role1 = 343000,
      role2 = 301102,
      role3 = 301201,
      role4 = 301309,
      sentence = "Feeling ashamed to look at Kiro, I had to turn to the others. However, the corner of my eye couldn't help but sweep over him.",
